use vstd::prelude::*;

verus! {

/// A simple interval type carried by the Laguerre object.
pub struct Interval {
    pub lo: f32,
    pub hi: f32,
}

/// A Laguerre-series “object” that stores coefficients and two intervals.
pub struct Laguerre {
    pub coefficients: Vec<f32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Construct a Laguerre series object from a given list of f32 coefficients.
///
/// Weakest preconditions:
/// - None. Any `Vec<f32>` is acceptable; no arithmetic is performed that could overflow,
///   and all values (including NaN/±inf) are allowed.
///
/// Strongest postconditions:
/// - Coefficients are stored with the same length and in the same order.
/// - For every valid index, the output coefficient equals the input coefficient
///   (bitwise-exact, as `f32` is a primitive Copy type).
/// - `domain` and `window` are exactly the unit interval [0.0, 1.0].
pub fn make_laguerre(coefficients: Vec<f32>) -> (out: Laguerre)
    ensures
        out.coefficients.len() == coefficients.len(),
        forall|i: int|
            0 <= i < coefficients.len()
            ==> out.coefficients[i] == coefficients[i],
        out.domain.lo == 0.0f32,
        out.domain.hi == 1.0f32,
        out.window.lo == 0.0f32,
        out.window.hi == 1.0f32,
{
    Laguerre {
        coefficients,
        domain: Interval { lo: 0.0f32, hi: 1.0f32 },
        window: Interval { lo: 0.0f32, hi: 1.0f32 },
    }
}

} // verus!

